-- 043. Разбор после финала: «Как всё было на самом деле» и ложные следы
alter table case_accusation add column if not exists debrief jsonb;
update case_accusation set debrief = '{"title": "Как всё было на самом деле", "truth": [{"when": "1994 год", "text": "Таможня задержала товар их общего кооператива. Фархад Мамаджанов взял вину на себя и сел. Игорь обещал сохранить его долю и помогать семье."}, {"when": "1995 год", "text": "Пока Фархад сидел, Игорь и Данияр приватизировали базу на Ташкентской и оформили её на себя. Фамилии Фархада в бумагах нет."}, {"when": "Конец 1995 — октябрь 1996", "text": "В конце девяносто пятого Фархад вышел. Денег нет, партия из Урумчи пропала, кредиторы приходили к нему домой и говорили про его дочь. В октябре он попросил у Игоря свою долю. Игорь отказал при Данияре: «Я тебя садиться не просил». Фархад ушёл молча."}, {"when": "За две недели", "text": "Фархад списал Ерлану старый долг в обмен на расписание хозяина. Так он узнал про четверги: Игорь отпускает водителя и едет на дачу один. Племяннику Олжасу он сказал: «Он нашу семью обокрал. Берём своё, никто не пострадает»."}, {"when": "Четверг, 21 ноября", "text": "Утром Фархад отправил дочь к родне в Ташкент. В 17:40, уже в темноте, они с Олжасом схватили Игоря у ворот дачи и затолкали в «Волгу». Пейджер упал в арык под листья. Игоря связали поверх рукавов куртки и спустили в подвал пустого дома Шмидтов в Горном Гиганте. Вечером Олжас позвонил Валентине Петровне: шестьдесят тысяч, и ни слова милиции, иначе внучку она больше не увидит."}, {"when": "Пятница", "text": "Валентина Петровна и Данияр решили платить и молчать. Ночью Фархад сам спустил пленнику воду. Игорь узнал его по кашлю и по запаху «Беломора», но промолчал."}, {"when": "Суббота, 23 ноября", "text": "Данияр собрал сорок тысяч и тайком откопировал каждую купюру. Игорь через люк попросил Олжаса передать дяде: «Я тебя узнал. Пусть берёт деньги и отпускает, я никому не скажу». В 17:30 Олжас забрал пакет на остановке, Фархад подобрал его на «Волге». У Шмидтов Олжас отдал деньги и передал слова Игоря. Фархад отсчитал ему три тысячи и отослал в общежитие: «Утром отпущу»."}, {"when": "Суббота, ночь", "text": "В семь вечера в Горном Гиганте и на Кок-Тобе отключили свет. Фархад сидел в тёмном доме с керосиновой лампой. Около десяти он спустился в подвал и задушил Игоря. Тот успел поцарапать ему руку. В 23:20 Фархад в перчатках вывез тело на машине Игоря, на Кок-Тобе пересадил его за руль, накатом закатил машину в гараж и завёл двигатель. В час ночи пошёл первый снег и накрыл его следы."}, {"when": "Воскресенье", "text": "Тело нашёл водитель Виктор. РОВД за час написал «угорел». Днём Фархад отдал часть долларов кредитору, остальное спрятал в мешок с рисом. Ботинки вымыл, но не выбросил. Вечером пришёл к Валентине Петровне «как старый друг», оставил конверт на похороны, а в прихожей тихо сказал: «Береги Дашу, никому ни слова»."}, {"when": "Где он ошибся", "text": "Пять купюр из выкупа в конверте «на похороны». Ботинки с порезом на каблуке, которые он не выбросил. Отпечатки на люке и на лампе. Царапины на руке. И алиби «сидел при свечке» в «Орбите», где в ту субботу свет не отключали."}], "false_leads": [{"who": "Несчастный случай", "why": "Свет и правда отключали, гараж закрыт, двигатель работал, ключ в зажигании. Так и написал РОВД.", "why_not": "Кан: удушение, угарного газа в крови нет, следы верёвок поверх рукавов, щетина и обезвоживание — двое суток он где-то был. А гараж в пятницу днём стоял пустой, это видела Алия."}, {"who": "Алия, бывшая жена", "why": "Спор из-за дачи, «чтоб ты сдох» при свидетелях, ключи от ворот и дома, её следы у гаража, она врала, что не была на даче.", "why_not": "Была на даче в пятницу днём — забрала папку с документами. Следы старые, дневные. В субботу ночью давала наркоз на операции. Про четверги не знала."}, {"who": "Данияр, партнёр", "why": "Выводил деньги, Игорь грозил ему тюрьмой, база остаётся ему. Белая машина, 43-й размер, вторая группа крови, ложь про субботний вечер.", "why_not": "Врал, чтобы скрыть выкуп и «чёрную» кассу. В субботу вечером был у Валентины Петровны, его видела соседка. Ботинки и пальцы не совпали. Ксерокопии купюр он отдал сам — по ним и нашли убийцу."}, {"who": "Ерлан, охранник", "why": "Бывший милиционер, знал расписание хозяина и врал про Фархада.", "why_not": "Продал четверги за списанный долг, но о похищении не знал. В ту ночь был на смене и каждый час отзванивался на пульт. Пособник, не убийца."}, {"who": "Олжас, племянник", "why": "Высокий парень с остановки, три тысячи из выкупа за подкладкой, его пальцы на люке.", "why_not": "Похищал и сторожил, но верил, что Игоря отпустят. В ночь убийства сидел в общежитии. Слова Игоря «я тебя узнал» передал дяде сам — и этим, не зная того, решил его судьбу."}, {"who": "Валентина Петровна, мать", "why": "Врала, что сын уехал в Бишкек, и молчала про звонки.", "why_not": "Боялась за внучку. Похитители велели молчать, а Фархад в воскресенье повторил это ещё раз, уже «по-дружески»."}]}'::jsonb where case_id = '029e23c3-01e0-5d19-a0e7-3e0c2446ebab';
notify pgrst, 'reload schema';
select jsonb_array_length(debrief->'truth') as truth, jsonb_array_length(debrief->'false_leads') as leads from case_accusation where case_id = '029e23c3-01e0-5d19-a0e7-3e0c2446ebab';
